    "source": "# ═══════════════════════════════════════════════════════════\n# PlantLang — مثال 05: نظام درجات حقيقي\n# ═══════════════════════════════════════════════════════════\n\nMISSION: SAFE.\nPLANT math.\nPLANT strings.\nPLANT lists.\n\nROOT PASS_MARK TO 50.\nROOT MAX_MARK  TO 100.\n\n# ── تعريف SPECIES الطالب ──────────────────────────────────\n1\\ SPECIES Student,\n2\\   VAR name(TX)   TO \"مجهول\".\n2\\   VAR id(NUM)    TO 0.\n2\\   VAR scores(LIST).\n\n2\\   ACTION add_score(subject(TX), score(NUM)),\n3\\     IF score LESS THAN 0,    GIVE \"درجة سالبة غير صالحة\".\n3\\     IF score GREATER THAN MAX_MARK, GIVE \"درجة تتجاوز الحد\".\n3\\     PUT score INTO SELF:scores.\n3\\     GIVE score.\n2\\   /ACTION.\n\n2\\   ACTION average(),\n3\\     IF COUNT SELF:scores IS 0, GIVE 0.\n3\\     REAP total FROM lists:AVERAGE, SELF:scores.\n3\\     REAP rounded FROM math:ROUND, total, 1.\n3\\     GIVE rounded.\n2\\   /ACTION.\n\n2\\   ACTION grade(),\n3\\     REAP avg FROM SELF:average.\n3\\     MATCH avg,\n4\\       IS BETWEEN 90 100 YIELD GIVE \"A — ممتاز\".\n4\\       IS BETWEEN 80 89  YIELD GIVE \"B — جيد جداً\".\n4\\       IS BETWEEN 70 79  YIELD GIVE \"C — جيد\".\n4\\       IS BETWEEN 50 69  YIELD GIVE \"D — مقبول\".\n4\\       ELSE              YIELD GIVE \"F — راسب\".\n3\\     \\\\.\n2\\   /ACTION.\n\n2\\   ACTION report(),\n3\\     REAP avg   FROM SELF:average.\n3\\     REAP grade FROM SELF:grade.\n3\\     REAP max   FROM lists:SORT, SELF:scores.\n3\\     GIVE SELF:name + \" | معدل: \" + avg + \" | \" + grade.\n2\\   /ACTION.\n1\\ /SPECIES.\n\n# ── إنشاء الطلاب ──────────────────────────────────────────\n1\\ BLOOM Student AS s1.\n1\\ SET s1:name TO \"أحمد علي\".\n1\\ SET s1:id   TO 1001.\n\n1\\ BLOOM Student AS s2.\n1\\ SET s2:name TO \"فاطمة حسين\".\n1\\ SET s2:id   TO 1002.\n\n1\\ BLOOM Student AS s3.\n1\\ SET s3:name TO \"محمد كريم\".\n1\\ SET s3:id   TO 1003.\n\n# ── إضافة الدرجات ─────────────────────────────────────────\n1\\ REAP _ FROM s1:add_score, \"رياضيات\", 85.\n1\\ REAP _ FROM s1:add_score, \"علوم\",    90.\n1\\ REAP _ FROM s1:add_score, \"عربي\",    78.\n1\\ REAP _ FROM s1:add_score, \"إنكليزي\", 92.\n\n1\\ REAP _ FROM s2:add_score, \"رياضيات\", 95.\n1\\ REAP _ FROM s2:add_score, \"علوم\",    88.\n1\\ REAP _ FROM s2:add_score, \"عربي\",    91.\n1\\ REAP _ FROM s2:add_score, \"إنكليزي\", 87.\n\n1\\ REAP _ FROM s3:add_score, \"رياضيات\", 45.\n1\\ REAP _ FROM s3:add_score, \"علوم\",    52.\n1\\ REAP _ FROM s3:add_score, \"عربي\",    48.\n1\\ REAP _ FROM s3:add_score, \"إنكليزي\", 55.\n\n# ── تقرير كل طالب ─────────────────────────────────────────\n1\\ CREATE students(LIST) TO.\n1\\ PUT s1 INTO students.\n1\\ PUT s2 INTO students.\n1\\ PUT s3 INTO students.\n\n1\\ SHOW \"═══ تقرير الدرجات النهائي ═══\".\n\n1\\ REAP r1 FROM s1:report.\n1\\ REAP r2 FROM s2:report.\n1\\ REAP r3 FROM s3:report.\n\n1\\ SHOW r1.\n1\\ SHOW r2.\n1\\ SHOW r3.\n\n# ── كشف النتيجة (نجاح/رسوب) ─────────────────────────────\n1\\ SHOW \"\".\n1\\ SHOW \"═══ كشف النتيجة ═══\".\n\n1\\ REAP avg1 FROM s1:average.\n1\\ REAP avg2 FROM s2:average.\n1\\ REAP avg3 FROM s3:average.\n\n1\\ IF avg1 GREATER THAN PASS_MARK, SHOW s1:name + \" — ناجح ✓\".\n1\\ IF avg2 GREATER THAN PASS_MARK, SHOW s2:name + \" — ناجح ✓\".\n1\\ IF avg3 LESS THAN PASS_MARK,    SHOW s3:name + \" — راسب ✗\".\n\n# ── حفظ التقرير لملف ─────────────────────────────────────\n1\\ TAP \"results.txt\" MODE:MARK AS outfile.\n1\\ INFUSE outfile WITH \"تقرير درجات 2025\".\n1\\ INFUSE outfile WITH r1.\n1\\ INFUSE outfile WITH r2.\n1\\ INFUSE outfile WITH r3.\n1\\ SEAL outfile.\n\n1\\ SHOW \"\".\n1\\ SHOW \"تم حفظ التقرير في results.txt ✓\".\n"
